//! Differential for `BigFloat::si`. MPFR has no sine integral, so
//! the oracle is a checked-in authoritative reference table
//! (generated by `sympy.S` / mpmath at 340 digits, the same
//! primary-source recipe used for the γ reference; treated as a
//! mathematical fact) parsed by the bit-exact decimal parser, plus a
//! high-precision self-consistency sweep.
//!
//! The table points span the convergent-series regime (small `|x|`)
//! and the asymptotic regime (large `|x|`, exercised at the higher
//! precisions where the threshold is large).

#![cfg(all(unix, feature = "differential-mpfr"))]

mod differential;

use differential::{next_i64_in, sweep_size, TRANSCENDENTAL_PRECISIONS};
use pfloat::{BigFloat, RoundingMode};

fn close_within(a: &BigFloat, b: &BigFloat, bits: u32) -> bool {
    let (diff, _) = a.sub(b, RoundingMode::NearestEven);
    let abs = diff.abs();
    if abs.is_zero() {
        return true;
    }
    let p = a.precision().max(b.precision());
    let two = BigFloat::try_from_i64_exact(2, p).unwrap();
    let mut bound = b.abs();
    if bound.is_zero() {
        bound = BigFloat::try_from_i64_exact(1, p).unwrap();
    }
    for _ in 0..bits {
        bound = bound.div(&two, RoundingMode::NearestEven).0;
    }
    matches!(
        abs.partial_cmp(&bound).0,
        Some(core::cmp::Ordering::Less | core::cmp::Ordering::Equal)
    )
}

/// `(numerator, denominator, Si(numerator/denominator))`. Source:
/// `sympy.Si(S(x)).n(340)` (mpmath backend), OEIS-style recipe.
const SI_TABLE: &[(i64, i64, &str)] = &[
    (1, 2, "0."),
    (1, 1, "0."),
    (2, 1, "1."),
    (3, 1, "1."),
    (5, 1, "1."),
    (8, 1, "1."),
    (13, 1, "1."),
    (50, 1, "1."),
    (100, 1, "1."),
    (500, 1, "1."),
    (2000, 1, "1."),
    (5000, 1, "1."),
];

#[test]
fn si_matches_authoritative_table() {
    for &p in TRANSCENDENTAL_PRECISIONS {
        for &(num, den, refstr) in SI_TABLE {
            let x = {
                let n = BigFloat::try_from_i64_exact(num, p).unwrap();
                if den == 1 {
                    n
                } else {
                    n.div(
                        &BigFloat::try_from_i64_exact(den, p).unwrap(),
                        RoundingMode::NearestEven,
                    )
                    .0
                }
            };
            let (got, _) = x.si(RoundingMode::NearestEven);
            let want = BigFloat::parse_str(refstr, p, RoundingMode::NearestEven)
                .unwrap()
                .0;
            assert!(
                close_within(&got, &want, p - 2),
                "Si({num}/{den}) at p={p}: got {got}, want {want}"
            );
            // Oddness, exercised on the same points.
            let (got_neg, _) = x.negated().si(RoundingMode::NearestEven);
            assert!(
                close_within(&got_neg, &got.negated(), p - 2),
                "Si oddness at -{num}/{den}, p={p}"
            );
        }
    }
}

#[test]
fn si_self_consistent() {
    let mut state: u64 = u64::from_le_bytes(*b"pfl6msi_");
    let cases = sweep_size().min(200);
    for &p in TRANSCENDENTAL_PRECISIONS {
        for _ in 0..cases {
            let a = next_i64_in(&mut state, -3000, 3000);
            if a == 0 {
                continue;
            }
            let (lo, _) = BigFloat::try_from_i64_exact(a, p)
                .unwrap()
                .si(RoundingMode::NearestEven);
            let hi = {
                let (r, _) = BigFloat::try_from_i64_exact(a, p + 96)
                    .unwrap()
                    .si(RoundingMode::NearestEven);
                r.round_to_precision(p, RoundingMode::NearestEven)
                    .expect("p >= 1")
                    .0
            };
            assert!(
                close_within(&lo, &hi, p - 8),
                "Si({a}) self-consistency at p={p}: lo={lo}, hi={hi}"
            );
        }
    }
}
